contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public test function: attempt to call setOwner as InvMutTest and ensure it either reverts
    // or, if it returns, that owner was set to the provided address. In this contract we expect calls
    // from InvMutTest (not admin) to revert, so we assert owner remains unchanged when call reverts.
    function run(address newOwner) public payable {
        require(true);
        // read owner before
        address ownerBefore = c.owner();
        bool reverted;
        try c.setOwner(newOwner) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();
        // General rule: if the call reverted, owner must be unchanged; if it didn't revert, owner must equal newOwner.
        assert( (reverted && ownerAfter == ownerBefore) || (!reverted && ownerAfter == newOwner) );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
