    function run(address newOwner) public payable {
        require(address(c) != address(0));
        // read owner before
        address ownerBefore = c.owner();

        bool reverted;
        bool returned;
        // Try calling setOwner; it may revert (onlyAdmin). Capture whether it reverted and the return if not.
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            returned = success;
        } catch {
            reverted = true;
            returned = false;
        }

        address ownerAfter = c.owner();

        // General rule: if the call reverted then owner unchanged; if it returned then it must have returned true and owner updated to newOwner.
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && returned && ownerAfter == newOwner));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: candidate new owner and an address to observe
    function run(address candidate) public payable {
        require(true);
        // read owner before the call
        address ownerBefore = c.owner();

        bool reverted;
        bool ret = false;
        try c.setOwner(candidate) returns (bool ok) {
            reverted = false;
            ret = ok;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // General rule: if setOwner reverted, owner must be unchanged; if it returned, owner must equal the candidate and the return value is true
        assert((reverted && ownerAfter == ownerBefore) || (!reverted && ownerAfter == candidate && ret == true));
    }

    receive() external payable {}
}

