contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner) public payable {
        // read owner before
        address ownerBefore = c.owner();
        bool reverted;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // After the call, read owner
        address ownerAfter = c.owner();
        // General invariant: if call reverted then it cannot have returned true; if it didn't revert it must have returned true and owner equals newOwner.
